const angles = {
  0: { goal: "soft re-open, no pitch, ask if the problem still exists",
       cta: "a one-line reply telling me if this is still on your plate" },
  1: { goal: "share one specific insight or result relevant to their industry",
       cta: "ask if they want the 2-minute breakdown" },
  2: { goal: "polite breakup email, give them an easy exit",
       cta: "reply 'no' and I'll close your file" }
};

return $input.all().map(item => {
  const l = item.json;
  const daysCold = Math.floor(
    (Date.now() - new Date(l.last_contact_date)) / 86400000
  );
  const priority = (l.deal_value > 5000 ? 2 : 1) + (daysCold > 365 ? 0 : 1);

  return {
    json: {
      ...l,
      days_cold: daysCold,
      priority,
      angle: angles[l.touch_count].goal,
      cta: angles[l.touch_count].cta
    }
  };
});

