const raw = $json.output?.[0]?.content?.[0]?.text ?? $json.message?.content ?? $json.content ?? "";
let parsed;
try {
  parsed = typeof raw === "string"
    ? JSON.parse(raw.replace(/```json|```/g, "").trim())
    : raw;
} catch (e) {
  return [{ json: { ...$('Process Leads One at a Time').item.json, valid: false, fail: "unparseable" } }];
}

const body = (parsed.body || "").trim();
const words = body.split(/\s+/).length;

// Strip whatever sign-off the model wrote
const cleanBody = body
  .replace(/\n*\s*(best regards|regards|thanks|thank you|sincerely)?[,]?\s*\n*\s*CJ\s*$/i, '')
  .trim();

const emailBody = `${cleanBody}\n\nBest regards,\nCJ`;

const paragraphs = cleanBody
  .split(/\n+/)
  .filter(p => p.trim())
  .map(p => `<p style="margin:0 0 16px 0; font-size:15px; line-height:1.6; color:#2d2d2d;">${p.trim()}</p>`)
  .join('');

const emailBodyHtml = `
<div style="font-family: Arial, Helvetica, sans-serif; max-width:560px; margin:0 auto; padding:0;">
  <div style="padding:20px 24px; border-bottom:2px solid #1a1a1a;">
    <span style="font-size:16px; font-weight:bold; color:#1a1a1a; letter-spacing:0.5px;">CJ FRANCO</span>
    <span style="font-size:12px; color:#888; margin-left:8px;">Web &amp; Automation Development</span>
  </div>
  <div style="padding:24px;">
    ${paragraphs}
    <p style="margin:24px 0 0 0; font-size:15px; line-height:1.6; color:#2d2d2d;">
      Best regards,<br>
      <strong>CJ</strong>
    </p>
  </div>
  <div style="padding:16px 24px; border-top:1px solid #e5e5e5; font-size:11px; color:#999; line-height:1.5;">
    You're receiving this because we worked together previously.
    If you'd rather not hear from us again, just reply with "unsubscribe" and we'll remove you from this list.
  </div>
</div>
`.trim();

const checks = {
  hasBody:        body.length > 40,
  lengthOk:       words >= 40 && words <= 140,
  noPlaceholders: !/\[.*?\]|\{\{.*?\}\}|XYZ|Lorem/i.test(body),
  noAiTells:      !/as an AI|I hope this email finds you well|circling back/i.test(body),
  hasSubject:     (parsed.subject || "").length > 5 && parsed.subject.length < 70,
  nameCorrect:    body.includes($('Process Leads One at a Time').item.json.first_name)
};

const failed = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);

// Prefix the subject deterministically - never trust the AI to add this reliably
const finalSubject = `[Reactivation] ${parsed.subject || ''}`;

return [{ json: {
  ...$('Process Leads One at a Time').item.json,
  subject: finalSubject,
  body,
  emailBody,
  emailBodyHtml,
  valid: failed.length === 0,
  fail: failed.join(",")
}}];

const reasons = {
  hasBody:        "the email body came back empty or too short to be usable",
  lengthOk:       "the email length was outside the target range",
  noPlaceholders: "the draft contained leftover placeholder text",
  noAiTells:      "the draft used generic phrasing we don't want in outbound emails",
  hasSubject:     "the subject line was missing or badly formed",
  nameCorrect:    "the lead's name wasn't used correctly in the email"
};

const item = $input.first().json;
const failedChecks = (item.fail || "").split(",").filter(Boolean);
const explanations = failedChecks.map(f => reasons[f] || f);

const summary = explanations.length === 1
  ? explanations[0]
  : explanations.slice(0, -1).join(", ") + " and " + explanations[explanations.length - 1];

const message =
  `⚠️ A draft email needs review\n\n` +
  `Lead: ${item.first_name} — ${item.company}\n` +
  `Contact: ${item.email}\n\n` +
  `Reason: ${summary}.\n\n` +
  `This email was held back automatically and was not sent. No action needed unless you want to review or send it manually.`;

return [{ json: { ...item, alert_message: message } }];
